#!/usr/bin/env node
// Provision the non-owner application role for RLS enforcement (default:
// daobrew_app — LOGIN NOSUPERUSER NOBYPASSRLS + table grants + default
// privileges; SQL generated by src/engine/postgres-rls.ts).
//
// IMPORTANT: run this as the SAME owner role that runs
// scripts/bootstrap-postgres-schema.mjs. `ALTER DEFAULT PRIVILEGES` binds to
// the EXECUTING role — grants on future tables only apply to tables later
// created by that role, so provisioning from a different role would leave the
// app role without privileges on tables added by future bootstraps.
//
// Password: env DAOBREW_APP_ROLE_PASSWORD only — never argv, never logged,
// never echoed. The generated SQL always carries the psql variable
// placeholder :'app_password'; the value is supplied at apply time via
// `psql -v app_password=...` (psql quotes it safely server-side).
//
// Idempotent re-runs: if the role already exists in pg_roles, CREATE ROLE is
// skipped (it is not idempotent) and the GRANT / ALTER DEFAULT PRIVILEGES
// statements are re-applied; the existing password is left untouched.
//
// Usage:
//   node scripts/provision-app-role.mjs [--role=daobrew_app] [--dry-run]
//
// Env contract (same routing as bootstrap-postgres-schema.mjs):
//   DAOBREW_APP_ROLE_PASSWORD           (required unless --dry-run or role exists)
//   DAOBREW_POSTGRES_URL=...            (URL mode, e.g. Neon owner URL)
//   DAOBREW_POSTGRES_DB / _USER / _PASSWORD / _PORT   (compose mode)

import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const scriptDir = dirname(fileURLToPath(import.meta.url));
const packageDir = resolve(scriptDir, "..");
const workspaceDir = resolve(packageDir, "..");

function argValue(name, fallback) {
  const prefix = `--${name}=`;
  const found = process.argv.slice(2).find((arg) => arg.startsWith(prefix));
  return found ? found.slice(prefix.length) : fallback;
}

if (process.argv.includes("--help") || process.argv.includes("-h")) {
  console.log([
    "Usage: node scripts/provision-app-role.mjs [--role=daobrew_app] [--dry-run]",
    "",
    "Creates the non-owner application role (LOGIN NOSUPERUSER NOBYPASSRLS) and",
    "grants it CRUD on all public tables plus matching default privileges, so",
    "row-level security is enforced on its connections. Re-runs are idempotent:",
    "CREATE ROLE is skipped when the role exists; grants are re-applied.",
    "",
    "Run as the same owner role that runs bootstrap-postgres-schema.mjs",
    "(ALTER DEFAULT PRIVILEGES binds to the executing role).",
    "",
    "  --role=NAME   role to provision (default daobrew_app)",
    "  --dry-run     print the provisioning SQL (with the :'app_password'",
    "                placeholder intact) without connecting; no password needed",
    "",
    "Env contract:",
    "  DAOBREW_APP_ROLE_PASSWORD   password for CREATE ROLE (env only — never",
    "                              argv, never printed)",
    "  DAOBREW_POSTGRES_URL / DAOBREW_POSTGRES_DB etc. route psql exactly like",
    "  bootstrap-postgres-schema.mjs (Neon URL vs local compose service).",
  ].join("\n"));
  process.exit(0);
}

const dryRun = process.argv.includes("--dry-run");
const roleName = argValue("role", "daobrew_app");

const rlsModulePath = resolve(packageDir, "dist", "src", "engine", "postgres-rls.js");
if (!existsSync(rlsModulePath)) {
  throw new Error("Missing dist/src/engine/postgres-rls.js. Run `npm run build` in daobrew-wellness-mcp first.");
}
const { appRoleProvisionSql } = await import(rlsModulePath);

// Validates the role name (simple lowercase SQL identifier) and always emits
// the :'app_password' placeholder — never a literal password.
const provisionSql = appRoleProvisionSql(roleName);
const statements = provisionSql.split("\n").filter((line) => line.trim().length > 0);
if (!statements[0]?.startsWith("CREATE ROLE ")) {
  throw new Error("Unexpected provisioning SQL shape: expected CREATE ROLE as the first statement");
}
const grantsOnlySql = `${statements.slice(1).join("\n")}\n`;

if (dryRun) {
  console.log(provisionSql.trim());
  process.exit(0);
}

const { postgresCliArgs } = require("../dist/src/graph-db.js");

// The URL (when present) carries credentials — and the apply argv carries the
// app-role password via -v — so a raw execFileSync error would leak secrets
// through err.message (which embeds the full command). Rethrow with stderr only.
function runPsql(argv, input) {
  try {
    return execFileSync("docker", argv, {
      cwd: workspaceDir,
      encoding: "utf-8",
      input,
    });
  } catch (err) {
    const stderr = typeof err?.stderr === "string" ? err.stderr.trim() : "";
    throw new Error(stderr || "App-role provisioning psql command failed");
  }
}

const psqlArgs = postgresCliArgs();

// CREATE ROLE is not idempotent (no IF NOT EXISTS) — pre-check pg_roles.
const existing = runPsql(psqlArgs, `SELECT 1 FROM pg_roles WHERE rolname = '${roleName}';\n`).trim();

if (existing === "1") {
  runPsql(psqlArgs, grantsOnlySql);
  console.log(`role ${roleName} already exists — skipped CREATE ROLE (password unchanged), re-applied grants + default privileges`);
} else {
  const password = process.env.DAOBREW_APP_ROLE_PASSWORD || "";
  if (!password) {
    console.error("DAOBREW_APP_ROLE_PASSWORD is required to create the role (env only; use --dry-run to preview the SQL).");
    process.exit(1);
  }
  // Password travels via stdin (\set), never argv — a `-v app_password=...`
  // child arg would be briefly visible to local `ps`/`docker inspect`.
  const setPassword = `\\set app_password '${password.replace(/'/g, "''")}'\n`;
  runPsql(psqlArgs, setPassword + provisionSql);
  console.log(`role ${roleName} created (LOGIN NOSUPERUSER NOBYPASSRLS) with grants + default privileges`);
}
